import{_ as f,l as a,o as m,b as h,d as r,m as l,q as n,f as t}from"./chunks/framework.Tf23FRXt.js";const d="/images/icons/061545.png",B=JSON.parse('{"title":"非战斗内容","description":"","frontmatter":{},"headers":[{"level":2,"title":"RP(角色扮演)","slug":"rp-角色扮演","link":"#rp-角色扮演","children":[]},{"level":2,"title":"永结同心","slug":"永结同心","link":"#永结同心","children":[]},{"level":2,"title":"探索笔记","slug":"探索笔记","link":"#探索笔记","children":[]},{"level":2,"title":"幻化/投影","slug":"幻化-投影","link":"#幻化-投影","children":[]},{"level":2,"title":"钓鱼","slug":"钓鱼","link":"#钓鱼","children":[]},{"level":2,"title":"收集","slug":"收集","link":"#收集","children":[{"level":3,"title":"坐骑","slug":"坐骑","link":"#坐骑","children":[]},{"level":3,"title":"宠物","slug":"宠物","link":"#宠物","children":[]},{"level":3,"title":"乐谱","slug":"乐谱","link":"#乐谱","children":[]},{"level":3,"title":"幻卡","slug":"幻卡","link":"#幻卡","children":[]},{"level":3,"title":"成就","slug":"成就","link":"#成就","children":[]}]}],"relativePath":"topic/relax.htm.md","filePath":"topic/relax.md","lastUpdated":1791101830000}'),u={name:"topic/relax.htm.md"};function g(k,e,b,E,x,P){const o=a("FloatTOC"),i=a("Quest"),p=a("item"),s=a("Pos");return m(),h("div",null,[e[19]||(e[19]=r("h1",{id:"非战斗内容",tabindex:"-1"},"非战斗内容",-1)),l(o),e[20]||(e[20]=n('<p>以下的内容不需要你参与任何战斗，也不要求你有满级职业，只希望你能从中感到快乐。</p><h2 id="rp-角色扮演" tabindex="-1">RP (角色扮演)</h2><p>说到 RPG 怎么能不说 RP？RP 就是 Role Play（角色扮演），指玩家自发进行的角色扮演活动。</p><p>在个人状态中（按 <code>O</code> 打开小队列表，在自己的名字上右键，可以修改自己的个人状态），有一个<mark>角色扮演</mark>的选项。把自己的状态切换到角色扮演中，你的 ID 前面就会出现一个<img src="'+d+'" class="no-zoom sm-icon">标记，这样可以告诉其他人你在 RP。这个时候你就可以尽情 RP 啦，无论是中二的骑士发言，或者是剧情捏他的对话（<ins>请尽量避免在新人面前剧透，共同维护游戏环境</ins>），都是 RP 玩家的乐趣所在。最常见的轻度 RP 就有海都集体舞（大概是因为阳光好…）或者森都演唱会（森都是诗人的老家，主城里也有一个露天剧场，所以很多喜欢弹奏的玩家都喜欢在森都开音乐会）。</p><p>由于 FF14 提供了<a href="/topic/social.htm#住宅区与房屋">住宅区和房屋系统</a>，很多玩家也会在住宅区开 RP 店。这里虽然叫 RP 店，但是玩法通常不局限于 RP，有密室逃脱、迷宫解谜类型的，也有酒吧、夜店、树洞、茶馆类型的，乃至<a href="https://zhuanlan.zhihu.com/p/64791226" target="_blank" rel="noreferrer">话剧表演</a>，包括中重度 RP 的跑团玩法等等。想了解更多 RP 店的情况，可以关注<a href="https://www.weibo.com/u/6212462969" target="_blank" rel="noreferrer">艾欧泽亚 RP 情报站微博</a>、<a href="https://weibo.com/u/7722097704" target="_blank" rel="noreferrer">艾欧泽亚见闻笔记</a>。</p><p>国际服玩家还制作了各种 “电影”，如果感兴趣的话可以参考<a href="./other.htm#玩家自制电影">玩家自制电影</a>页面。</p><p>如果你是一名想要尝试社交的玩家，也可以从 RP 玩法开始体验哦～</p><h2 id="永结同心" tabindex="-1">永结同心</h2><p>永结同心是 FF14 中特别的对象立下永远在一起的誓言的誓约仪式。双方在<a href="https://qu.sdo.com/tools-shop?merchantId=1&amp;currentPage=1&amp;pageSize=40&amp;order=0&amp;keyword=&amp;tagId=&amp;baseCategoryId=5&amp;baseCategoryName=%E6%B0%B8%E7%BB%93%E5%90%8C%E5%BF%83&amp;childCategoryId=" target="_blank" rel="noreferrer">商城</a>购买结婚套餐（有免费、88、168 三档）之后，会获得重要道具誓约手镯，接下来前往东森大教堂做一系列烙印任务，并预约教堂就可以举办典礼了。</p><p>88 和 168 的仪式套餐会赠送双方玩家双人大白鸡，并且为来参加婚礼的宾客赠送两个小宠物。另外在永结同心一周年之后，还可以再次向教堂预约纪念仪式。</p><p>关于永结同心的详细介绍和具体流程，可以查看<a href="http://act.ff.sdo.com/project/150420Marriage/" target="_blank" rel="noreferrer">官网特设页面</a>，里面详细说明了参加永结同心的任务流程等等细节。<s>和真实的婚礼一样，不少玩家也在这个活动中大闹乌龙，包括但不限于忘记时间、弄丢请柬等等…</s></p><p>完成所有任务的 2 人会获得同心戒指，双方都在相同服务器的话可以免费传送到对方身边，也经常被笑称为查房戒指。回到东森教堂把戒指退掉就算 “离婚” 了（允许单方面退戒指，但是对方的戒指不会自动失效）。</p><h2 id="探索笔记" tabindex="-1">探索笔记</h2>',13)),r("p",null,[e[0]||(e[0]=t("主线 20 级之后可以在格里达尼亚的魔女咖啡屋接受任务",-1)),l(i,{name:"被遗忘的探索笔记",type:"plus"}),e[1]||(e[1]=t("解锁",-1)),e[2]||(e[2]=r("mark",null,"探索笔记",-1)),e[3]||(e[3]=t("功能。",-1))]),r("blockquote",null,[e[10]||(e[10]=r("p",null,"解锁完探索笔记后，可在完成对应主线任务后，接以下任务开启对应版本探索笔记：",-1)),r("ul",null,[r("li",null,[e[4]||(e[4]=t("3.0 探索笔记：",-1)),l(i,{name:"苍穹下的风景",type:"plus"})]),r("li",null,[e[5]||(e[5]=t("4.0 探索笔记：",-1)),l(i,{name:"红莲中的风景",type:"plus"})]),r("li",null,[e[6]||(e[6]=t("5.0 探索笔记：",-1)),l(i,{name:"黑暗中的风景",type:"plus"})]),r("li",null,[e[7]||(e[7]=t("6.0 探索笔记：",-1)),l(i,{name:"晓月下的风景",type:"plus"})]),r("li",null,[e[8]||(e[8]=t("7.0 探索笔记（前半）：",-1)),l(i,{name:"黄金色的风景",type:"plus"})]),r("li",null,[e[9]||(e[9]=t("7.0 探索笔记（后半）：",-1)),l(i,{name:"黄金色的风景与新的记录",type:"plus"})])])]),e[21]||(e[21]=n('<p>探索笔记需要你在特定时间，在特定地点，完成特定动作。也就是 FF14 中的跳跳乐。在 2.x 的探索笔记中，当你抵达探索笔记所标示的地点，聊天窗口中会提示<mark>到达了探索笔记的目的地！</mark>，而 3.x 之后的探索笔记，则有一个明显的大蓝球，只要完成指定动作 (通常是 <code>/张望</code> ) 就可以记录探索笔记了。</p><p>探索笔记所要造访的地方，都是艾欧泽亚的美景，我自己也是在完成探索笔记的途中，发现这个世界真是 TM 的美爆了……</p><p>如果你想要挑战这部分内容，请记得自备<a href="https://tools.ffxiv.cn/lajipai/index.html" target="_blank" rel="noreferrer">探索笔记攻略</a>和<a href="https://annangela.github.io/FFXIVSightseeingGuide/#/" target="_blank" rel="noreferrer">天气预报</a>。当然另外也推荐学习一下滤镜，艾欧泽亚有丰富多样的景色，有很多玩家以在游戏中拍照作为自己的主要玩法。</p><p>完成探索笔记记录之后，可以在田园郡的画家那里购买画作，然后制作画框、画架就可以把这些画摆在家里。</p><h2 id="幻化-投影" tabindex="-1">幻化 / 投影</h2><p>自拍系统据说是为了帮助<a href="/topic/other.htm#光之老爹">光爹</a>拍摄而增强的… 在对话框输出 <code>/gpose</code> 或者 <code>/icam</code> 可以进入集体动作 / 观景模式，此时点击鼠标中键，就可以打开滤镜设置。</p><p>在滤镜设置中，可以像真正的摄影那样布置灯光进行拍摄。</p><p>另外为了更好地辅助拍摄，玩家们使用 Reshader 制作了<a href="https://weibo.com/1734754935/KjmswnZQL" target="_blank" rel="noreferrer"> Gshade</a>，使用这个补丁会让游戏画面变得更好看。不过由于它属于外挂插件，因此对电脑性能有额外的负担，另外也有可能影响正常界面 UI 的显示，所以如果电脑性能比较差，或者更喜欢专注于打本、打人，就不推荐啦。具体效果和设置方法请看上面的链接。</p><blockquote><p><a href="/basic/equip-looking.htm">如何试穿、投影、染色</a></p><p>装备获取途径：</p><ul><li><a href="/basic/equip-looking.htm">染色与投影</a></li><li><a href="/basic/item.htm">使用游戏市场获得装备</a></li><li><a href="/advanced/currency.htm">其他货币兑换</a></li><li><a href="/topic/shine.htm">发光武器</a>：武器试穿需要在试穿界面中选择 “拔出武器”（界面下方的小圆按钮）查看光效。</li></ul><p>幻化 / 投影参考网站：</p><ul><li><a href="https://mirapri.com/" target="_blank" rel="noreferrer">MIRAPRI SNAP</a>：日文幻化网站</li><li><a href="https://ffxiv.eorzeacollection.com/glamours" target="_blank" rel="noreferrer">Glamour Collection</a>：英文幻化网站</li><li><a href="https://www.ffxivsc.cn/" target="_blank" rel="noreferrer">光之收藏家</a>：中文幻化网站</li><li><a href="https://www.ffxivcollection.com/" target="_blank" rel="noreferrer">FFXIV ARMOURY COLLECTION</a> / <a href="https://weapon.ffxivcollection.com/" target="_blank" rel="noreferrer">FFXIV WEAPON COLLECTION</a>：装备 / 武器外观一览，右上角可切换英 / 日</li><li><a href="https://ff14-fc.com/" target="_blank" rel="noreferrer">Mirapri Life</a>（日语）：装备带散件特写外观一览网站。</li><li><a href="https://attire.jp/" target="_blank" rel="noreferrer">FF14 装備手帳</a>（日语）：以精灵族为模特的装备外观一览网站。</li><li><a href="https://connietarte.com/" target="_blank" rel="noreferrer">コニーのタルト</a>（日语）：以猫娘为模特的装备外观一览网站。</li></ul></blockquote><h2 id="钓鱼" tabindex="-1">钓鱼</h2><p>虽然钓鱼是一个采集职业，但是我还是要在休闲内容里提一嘴…… 如果说钓鱼和其他采集职业最大的不同之处…… 就是… 看脸！不挣钱！</p><p>如果你觉得自己是个欧皇或者单纯只是无聊，钓鱼确实是一项很适合的<s>休闲</s>活动。完成 50 级鱼皇任务可以获得 <strong>« 挥杆降龙 »</strong> 的称号，以及之后的 <strong>« 烟波钓徒 »</strong>，到海钓的 <strong>« 八爪旅人 »</strong>、<strong>« 龙马精神 »</strong> 等等称号也都是钓鱼独有的。</p><p>关于钓鱼的信息可以查看<a href="/topic/fisher.htm">钓鱼指南</a>以及<a href="/topic/ocean-fishing.htm">海钓手册</a>。</p><h2 id="收集" tabindex="-1">收集</h2><p>有些人像仓鼠，总有收集的癖好，这种事放在人类身上叫集邮。FF14 提供了多种收集玩法，总有一种满足你</p><h3 id="坐骑" tabindex="-1">坐骑</h3><p>在 20 级拿到自己的第一只陆行鸟之后，你就可以踏上坐骑收集的漫漫长路了。坐骑主要获取途径有金币购买、副本掉落和成就获得等等，可以查看<a href="https://ff14.huijiwiki.com/wiki/%E5%9D%90%E9%AA%91%E8%8E%B7%E5%8F%96%E6%96%B9%E5%BC%8F" target="_blank" rel="noreferrer">坐骑列表及获取方式</a>。</p><h3 id="宠物" tabindex="-1">宠物</h3><p>宠物就是跟宠，作为一个召唤我特别喜欢左手一只鸟，右手一只宠，身后带着个 <s>皮卡丘</s> 土豆的热闹生活。在 3.2 金碟游乐场追加了萌宠大赛之后，这些小宠物也有了自己的活跃场所。<a href="https://ff14.huijiwiki.com/wiki/%E5%AE%A0%E7%89%A9%E8%8E%B7%E5%8F%96%E6%96%B9%E5%BC%8F" target="_blank" rel="noreferrer">跟宠列表及获取方式</a>，<a href="/topic/gs-minion.htm">金碟萌宠之王介绍</a>。</p><h3 id="乐谱" tabindex="-1">乐谱</h3><p>有的时候你在打完 BOSS 之后，会掉落一张 “陈旧的乐谱”，这张乐谱可以由工匠搓成 “管弦乐琴乐谱”，然后你就可以右键吃掉它了。另外有一些购买 / 交换的乐谱直接就是成品，不需要工匠操刀。</p><p>吃掉的乐谱可以在旅馆，或者在安装了<strong>管弦乐琴</strong>的房屋中聆听（你只能试听自己拥有的乐谱，如果有想听的 BGM 但自己却没有，可以拜托工会大佬把它设置成公会房的 BGM (前提是大佬有这张乐谱）。这些乐谱都是 FF14 各个地方的 BGM，有一些还是很好听的。</p><p>乐谱的获得方式可以在游戏内的 “管弦乐琴乐谱手册” 中直接查询，所有的乐谱都是可以交易的，所以也可以上板子看看。<a href="https://tools.ffxiv.cn/lajipai/" target="_blank" rel="noreferrer">乐谱获取途径查询和试听</a>。</p><h3 id="幻卡" tabindex="-1">幻卡</h3><p>在金蝶打牌的光之赌徒们一定对这玩意儿无法自拔。初始卡组只能组 4 个一星卡 + 一张超一星卡，当你收集了足够多的卡牌，就可以提升卡组的星等限制。最高可以组三星卡组 (4 张三星卡 + 1 张超三星卡)。<a href="https://ff14.huijiwiki.com/wiki/%E4%B9%9D%E5%AE%AB%E5%B9%BB%E5%8D%A1%E5%8D%A1%E7%89%8C" target="_blank" rel="noreferrer">全列表及获取方式</a>，剩下内容请参照<a href="/topic/triple-triad.htm">金蝶游乐场</a>部分。</p>',25)),r("p",null,[e[11]||(e[11]=t("集齐 1~312 号幻卡之后还可以获得幻卡坐骑",-1)),l(p,{name:"魔法幻卡"}),e[12]||(e[12]=t("。",-1))]),e[22]||(e[22]=r("h3",{id:"成就",tabindex:"-1"},"成就",-1)),e[23]||(e[23]=r("p",null,[t("…… 我曾经想成为艾泽拉斯的博学者，然后就没有然后了。FF14 的成就相较而言少多了… 但有一些季节活动的成就已经绝版，某些成就可以获得宠物、坐骑和称号，具体都可以在游戏内查看，也可以使用"),r("a",{href:"https://ff14.huijiwiki.com/wiki/AchievementSearch",target:"_blank",rel:"noreferrer"},"成就检索器"),t("检索。")],-1)),r("p",null,[e[13]||(e[13]=t("完成成就之后，可以在成就列表中直接领取奖励，成就奖励一旦获得，就可以从失物招领人那里反复购买。另外在森都的乔纳森",-1)),l(s,{name:"格里达尼亚旧街",x:10.6,y:6.3}),e[14]||(e[14]=t("会自动把你的成就点数折算成",-1)),e[15]||(e[15]=r("strong",null,"成就币",-1)),e[16]||(e[16]=t("，可以使用成就币兑换各种装备、道具，",-1)),e[17]||(e[17]=r("a",{href:"https://ff14.huijiwiki.com/wiki/%E6%88%90%E5%B0%B1%E5%B8%81",target:"_blank",rel:"noreferrer"},"成就币兑换列表",-1)),e[18]||(e[18]=t("。",-1))])])}const w=f(u,[["render",g]]);export{B as __pageData,w as default};
